1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { zipStream } from "@/lib/zip";
4	
5	export const dynamic = "force-dynamic";
6	
7	// Everything is nested under a single folder named for the slug, the way a
8	// GitHub "Download ZIP" behaves — unzipping into the user's Downloads folder
9	// should produce one project directory, not scatter package.json and src/
10	// across whatever they happened to be sitting in.
11	function entryPath(slug: string, path: string): string {
12	  return `${slug}/${path}`;
13	}
14	
15	export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
16	  const user = await requireUser().catch(() => null);
17	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
18	  const { id } = await params;
19	
20	  // Scoped by userId in the same query as the id, so another user's project is
21	  // indistinguishable from a nonexistent one — no row, no files, no leak.
22	  const project = await db.project.findFirst({
23	    where: { id, userId: user.id },
24	    select: { id: true, slug: true },
25	  });
26	  if (!project) return Response.json({ error: "Project not found." }, { status: 404 });
27	
28	  // The draft source tree — the real Vite+React+TS project. `published: false`
29	  // matches how every other source read in this app is scoped; the build output
30	  // (kind: "build") is compiled artefacts nobody wants in a source export.
31	  const files = await db.projectFile.findMany({
32	    where: { projectId: project.id, published: false, kind: "source" },
33	    orderBy: { path: "asc" },
34	    select: { path: true, content: true, updatedAt: true },
35	  });
36	  if (files.length === 0) {
37	    return Response.json({ error: "Nothing to export yet." }, { status: 404 });
38	  }
39	
40	  // Slugs are generated as [a-z0-9-] only, but this header ends up as a
41	  // filename on the user's disk — re-assert that rather than trusting it.
42	  const filename = `${project.slug.replace(/[^a-zA-Z0-9._-]/g, "-")}.zip`;
43	
44	  const stream = zipStream(
45	    files.map((f) => ({
46	      path: entryPath(project.slug, f.path),
47	      content: f.content,
48	      modifiedAt: f.updatedAt,
49	    })),
50	  );
51	
52	  return new Response(stream, {
53	    headers: {
54	      "Content-Type": "application/zip",
55	      "Content-Disposition": `attachment; filename="${filename}"`,
56	      // Private source, and the archive is rebuilt on every request anyway.
57	      "Cache-Control": "no-store",
58	    },
59	  });
60	}
